<script lang="ts">
  import { onMount } from 'svelte';
  import { browser } from '$app/env';
  import { goto } from '$app/navigation';
  import { resolve } from '$app/paths';
  import qrcode from 'qrcode-generator';
  // White JPEG with an ISO 21496-1 gain map (+~3 stops); regenerated by `pnpm hdr`.
  // Renders brighter than SDR white on HDR screens, plain white everywhere else.
  import hdrWhiteUrl from '../lib/assets/hdr-white.jpg';
  import BookOpenIcon from '@lucide/svelte/icons/book-open';
  import CircleCheckIcon from '@lucide/svelte/icons/circle-check';
  import LockKeyholeIcon from '@lucide/svelte/icons/lock-keyhole';
  import Maximize2Icon from '@lucide/svelte/icons/maximize-2';
  import Minimize2Icon from '@lucide/svelte/icons/minimize-2';
  import RefreshCwIcon from '@lucide/svelte/icons/refresh-cw';
  import SaveIcon from '@lucide/svelte/icons/save';
  import ScanLineIcon from '@lucide/svelte/icons/scan-line';
  import ShareIcon from '@lucide/svelte/icons/share';
  import * as api from '../lib/api.js';
  import { isPhone, isStandalone } from '../lib/device.js';
  import { OPENID_KEY, extractOpenId, readOpenIdFromHash } from '../lib/pairing.js';
  import { Button } from '../lib/components/ui/button';
  import * as Card from '../lib/components/ui/card';
  import { Input } from '../lib/components/ui/input';
  import { Label } from '../lib/components/ui/label';
  import * as Alert from '../lib/components/ui/alert';
  import CopyButton from '../lib/components/copy-button.svelte';
  import PairingDialog from '../lib/components/pairing-dialog.svelte';
  import QrScanner from '../lib/components/qr-scanner.svelte';

  const REFRESH_MS = 10_000;

  const POWERSHELL_GITHUB =
    'powershell -NoProfile -c "iex (irm https://raw.githubusercontent.com/Naptie/wxmp-storage-dumper/main/scripts/install.ps1)"';
  const POWERSHELL_GITEE =
    'powershell -NoProfile -c "iex (irm https://gitee.com/naptie/wxmp-storage-dumper/raw/main/scripts/install.ps1)"';

  let openid = $state<string | null>(null);
  let booted = $state(false);

  // The QR is one persistent <svg> whose path data is swapped on refresh —
  // replacing the whole node every 10s would re-composite the surrounding
  // layers and trip WebKit's HDR gain-map flicker on the card behind it.
  let qrPath = $state<string | null>(null);
  let qrModules = $state<number | null>(null);
  let info = $state<api.CodeInfo | null>(null);
  let issuedAt = $state(0);
  let error = $state<string | null>(null);
  let countdown = $state(0);
  let busy = $state(false);

  let isFullscreen = $state(false);
  let fullscreenHint = $state<string | null>(null);

  /** Phone in a browser tab (not installed as an app) — drives the button bar's label/icon split. */
  let phoneBrowser = $state(false);
  /** Installed web app (any platform); a tab never becomes standalone mid-session. */
  let standalone = $state(false);

  // Whether the display can show HDR (gain-map) content at all; on non-HDR
  // screens the card keeps its plain white background.
  let hdrDisplay = $state(false);

  let pairingOpen = $state(false);
  let pairingOpenId = $state('');

  let scannerOpen = $state(false);
  let verifying = $state(false);
  let input = $state('');

  let timer: ReturnType<typeof setInterval> | null = null;
  let nextAt = 0;

  const inactive = $derived(info !== null && info.mackCode === 0 && info.passTime != null);

  onMount(() => {
    // A tab never becomes standalone mid-session, so one evaluation at mount suffices.
    standalone = isStandalone();
    phoneBrowser = isPhone() && !standalone;
    adoptOpenIdFromUrl();

    if (!openid) {
      const stored = localStorage.getItem(OPENID_KEY);
      if (stored && api.isValidOpenId(stored)) {
        openid = stored;
      }
    }
    if (openid && !(standalone || phoneBrowser)) {
      // Desktop never shows the live pass; one best-effort info fetch lets
      // the hub confirm which account is configured.
      loadHubInfo();
    } else if (openid) {
      start();
    }
    booted = true;

    const syncFullscreen = () => {
      isFullscreen = !!document.fullscreenElement;
    };
    syncFullscreen();
    document.addEventListener('fullscreenchange', syncFullscreen);

    const hdrMql = window.matchMedia('(dynamic-range: high)');
    const syncHdr = () => {
      hdrDisplay = hdrMql.matches;
    };
    syncHdr();
    hdrMql.addEventListener('change', syncHdr);

    const onHashChange = () => {
      adoptOpenIdFromUrl();
    };
    window.addEventListener('hashchange', onHashChange);

    return () => {
      if (timer) clearInterval(timer);
      document.removeEventListener('fullscreenchange', syncFullscreen);
      hdrMql.removeEventListener('change', syncHdr);
      window.removeEventListener('hashchange', onHashChange);
    };
  });

  /**
   * Adopt an openId handed over through the URL fragment (a pairing link).
   * The fragment is stripped immediately; it never reaches any server.
   */
  function adoptOpenIdFromUrl() {
    const url = new URL(location.href);
    const incoming = readOpenIdFromHash(url.hash);

    if (incoming && api.isValidOpenId(incoming)) {
      localStorage.setItem(OPENID_KEY, incoming);
      if (openid !== incoming) {
        openid = incoming;
        info = null;
        qrPath = null;
        qrModules = null;
        error = null;
        if (standalone || phoneBrowser) {
          start();
        } else {
          loadHubInfo();
        }
      }
    }

    if (url.hash) {
      history.replaceState(null, '', url.pathname + url.search);
    }
  }

  /** Desktop hub: one best-effort info fetch, purely to confirm the account. */
  function loadHubInfo() {
    if (!openid || info) return;
    api
      .fetchCodeInfo(openid)
      .then((i) => (info = i))
      .catch(() => {});
  }

  /**
   * Shared adoption path for every binding input (pasted ID/link, scanned
   * pairing code): verify against the API first, and only save when the
   * credential proves valid. Desktop then moves on to the install guide;
   * phone starts polling immediately.
   */
  async function adopt(candidate: string): Promise<boolean> {
    const extracted = extractOpenId(candidate);
    if (!extracted) {
      error = '未识别到有效的 Open ID 或配对链接。';
      return false;
    }
    verifying = true;
    error = null;
    try {
      const result = await api.verifyOpenId(extracted);
      if (!result.ok) {
        error = result.reason === 'network' ? `${result.message}，请稍后重试。` : result.message;
        return false;
      }
      localStorage.setItem(OPENID_KEY, extracted);
      openid = extracted;
      info = result.info;
      qrPath = null;
      qrModules = null;
      if (standalone || phoneBrowser) {
        start();
      } else {
        await goto(resolve('/guide'));
      }
      return true;
    } finally {
      verifying = false;
    }
  }

  async function submitInput() {
    await adopt(input);
  }

  async function onScan(text: string) {
    const extracted = extractOpenId(text);
    if (!extracted) {
      error = '二维码中未包含配对信息——请扫描电脑屏幕上的配对码。';
      return;
    }
    await adopt(extracted);
  }

  function forget() {
    if (!confirm('清除本机保存的 Open ID？')) return;
    localStorage.removeItem(OPENID_KEY);
    openid = null;
    qrPath = null;
    qrModules = null;
    info = null;
    error = null;
    input = '';
    pairingOpenId = '';
    if (timer) clearInterval(timer);
    timer = null;
  }

  function start() {
    poll().then(tick);
    if (!timer) timer = setInterval(tick, 500);
  }

  async function poll() {
    if (!openid || busy) return;
    busy = true;
    try {
      // Fetch the permission status block alongside the first QR; it is
      // also refreshed implicitly whenever info is cleared.
      if (!info) {
        info = await api.fetchCodeInfo(openid);
      }
      const payload = await api.fetchQr(openid);
      renderQr(payload.qr);
      issuedAt = payload.issuedAt;
      error = null;
      nextAt = Date.now() + REFRESH_MS;
    } catch (e) {
      error = e instanceof Error ? e.message : String(e);
      nextAt = Date.now() + 10000;
    } finally {
      busy = false;
    }
  }

  function tick() {
    countdown = Math.max(0, Math.ceil((nextAt - Date.now()) / 1000));
    if (nextAt && Date.now() >= nextAt) poll();
  }

  function renderQr(qr: string): void {
    // EC level 'L' matches the mini program's canvas renderer — the module
    // matrix is identical down to the mask pattern (verified).
    const q = qrcode(0, 'L');
    q.addData(qr);
    q.make();
    // Draw dark modules only; white comes from the card's HDR gain-map
    // background (an opaque white layer here would clamp that area to SDR).
    const n = q.getModuleCount();
    let d = '';
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) {
        if (q.isDark(r, c)) d += `M${c},${r}h1v1h-1z`;
      }
    }
    qrPath = d;
    qrModules = n;
  }

  /**
   * Fullscreen is a toggle: enter it, and come back out of it again.
   * `document.fullscreenElement` is the source of truth — it also flips when
   * the user leaves fullscreen with Esc or the browser's own affordance.
   */
  async function toggleFullscreen() {
    fullscreenHint = null;
    const root = document.documentElement;
    try {
      if (document.fullscreenElement) {
        await document.exitFullscreen();
      } else if (typeof root.requestFullscreen === 'function') {
        await root.requestFullscreen();
      } else {
        fullscreenHint = '当前浏览器不支持网页全屏。';
      }
    } catch (e) {
      fullscreenHint = `无法切换全屏：${e instanceof Error ? e.message : String(e)}`;
    }
  }

  /** Hand the credential over to another device via a pairing QR code. */
  function openPairing(id: string) {
    pairingOpenId = id;
    pairingOpen = true;
  }

  function issuedTime(ts: number): string {
    return new Date(ts).toLocaleTimeString('zh-CN', { hour12: false });
  }
</script>

<svelte:head>
  <title>慧湖通通行码</title>
  <meta name="description" content="慧湖通学生公寓通行二维码" />
</svelte:head>

{#if !browser || !booted}
  <!-- avoid SSR/CSR mismatch before localStorage is readable -->
  <div class="text-muted-foreground flex min-h-svh items-center justify-center">…</div>
{:else if !openid}
  {#if standalone}
    <!-- 已安装的 App：扫码绑定优先，手动粘贴兜底 -->
    <div class="flex min-h-svh items-center justify-center p-6">
      <Card.Root class="w-full max-w-xl">
        <Card.Header class="text-center">
          <Card.Title class="flex items-center justify-center gap-2">
            <ScanLineIcon class="size-5" />
            扫码绑定
          </Card.Title>
          <Card.Description>
            扫描电脑屏幕上的配对二维码，绑定后即可在本机显示通行码。
          </Card.Description>
        </Card.Header>
        <Card.Content class="flex flex-col gap-4">
          <Button size="lg" onclick={() => (scannerOpen = true)}>
            <ScanLineIcon />
            扫码绑定
          </Button>
          <p class="text-muted-foreground text-xs leading-5">
            首次使用请先在电脑上完成 Open ID
            绑定，然后在电脑的「手机安装指南」页点击「出示配对二维码」。
          </p>
          <details class="text-sm">
            <summary class="text-muted-foreground cursor-pointer select-none">
              无法扫码？手动粘贴导入
            </summary>
            <div class="mt-3 flex flex-col gap-2">
              <Label for="openid-input">Open ID 或配对链接</Label>
              <Input
                id="openid-input"
                bind:value={input}
                placeholder="粘贴 Open ID 或配对链接"
                autocomplete="off"
              />
              <Button variant="outline" disabled={verifying} onclick={submitInput}>
                {verifying ? '正在验证…' : '验证并绑定'}
              </Button>
            </div>
          </details>
          {#if error}
            <Alert.Root variant="destructive">
              <Alert.Title>出错</Alert.Title>
              <Alert.Description>{error}</Alert.Description>
            </Alert.Root>
          {/if}
        </Card.Content>
      </Card.Root>
    </div>
  {:else if phoneBrowser}
    <!-- 手机浏览器：绑定不属于这里，引导先安装 -->
    <div class="flex min-h-svh items-center justify-center p-6">
      <Card.Root class="w-full max-w-xl">
        <Card.Header>
          <Card.Title>慧湖通通行码</Card.Title>
          <Card.Description>首次使用，请先在电脑上完成绑定，再把本页面安装为 App。</Card.Description
          >
        </Card.Header>
        <Card.Content class="flex flex-col gap-4">
          <Button href={resolve('/guide')}>
            <BookOpenIcon />
            查看手机安装指南
          </Button>
          <details class="text-sm">
            <summary class="text-muted-foreground cursor-pointer select-none">
              已有 Open ID？手动粘贴导入
            </summary>
            <div class="mt-3 flex flex-col gap-2">
              <Label for="openid-input">Open ID 或配对链接</Label>
              <Input
                id="openid-input"
                bind:value={input}
                placeholder="粘贴 Open ID 或配对链接"
                autocomplete="off"
              />
              <Button variant="outline" disabled={verifying} onclick={submitInput}>
                {verifying ? '正在验证…' : '验证并绑定'}
              </Button>
            </div>
          </details>
          {#if error}
            <Alert.Root variant="destructive">
              <Alert.Title>出错</Alert.Title>
              <Alert.Description>{error}</Alert.Description>
            </Alert.Root>
          {/if}
        </Card.Content>
      </Card.Root>
    </div>
  {:else}
    <!-- 电脑：获取并验证 Open ID 的唯一入口 -->
    <div class="flex min-h-svh items-center justify-center p-6">
      <Card.Root class="w-full max-w-xl">
        <Card.Header>
          <Card.Title>慧湖通通行码</Card.Title>
          <Card.Description>首次使用，请先绑定账号 ID。</Card.Description>
        </Card.Header>
        <Card.Content class="flex flex-col gap-4">
          <div class="flex items-start gap-2">
            <LockKeyholeIcon class="text-muted-foreground mt-1.5 size-4 shrink-0" />
            <div class="text-muted-foreground text-sm leading-7">
              <p>绑定前，你需要先找到自己的账号 ID（Open ID）。</p>
              <p>需用一台 Windows 10/11 x64 电脑，并登录 Windows 微信 4.x。</p>
              <ol class="list-outside list-decimal space-y-1 pl-5">
                <li>
                  按 Win+R，粘贴并运行：
                  <div class="flex items-start gap-2">
                    <code class="bg-muted block flex-1 rounded px-2 py-1 text-xs break-all">
                      {POWERSHELL_GITHUB}
                    </code>
                    <CopyButton text={POWERSHELL_GITHUB} label="复制安装命令" />
                  </div>
                  <p>如遇到网络问题，请运行：</p>
                  <div class="flex items-start gap-2">
                    <code class="bg-muted block flex-1 rounded px-2 py-1 text-xs break-all">
                      {POWERSHELL_GITEE}
                    </code>
                    <CopyButton text={POWERSHELL_GITEE} label="复制备用安装命令" />
                  </div>
                </li>
                <li>按提示在微信中打开「慧湖通」（若已打开，请先完全关闭再重新打开）。</li>
                <li>
                  确认输出 <code>appId</code> 为 <code>wx2660b404a3b7575a</code>，复制
                  <code>openId</code>。
                </li>
                <li>在下方输入框中粘贴 Open ID，点击「保存并验证」。</li>
                <li>验证通过后，页面会自动进入安装指南，按指引发送到手机。</li>
              </ol>
            </div>
          </div>
          <div class="flex flex-col gap-2">
            <Label for="openid-input">Open ID</Label>
            <Input
              id="openid-input"
              bind:value={input}
              placeholder="在此处粘贴 Open ID"
              autocomplete="off"
            />
            <Button disabled={verifying} onclick={submitInput}>
              <SaveIcon />
              {verifying ? '正在验证…' : '保存并验证'}
            </Button>
          </div>
          {#if error}
            <Alert.Root variant="destructive">
              <Alert.Title>出错</Alert.Title>
              <Alert.Description>{error}</Alert.Description>
            </Alert.Root>
          {/if}
        </Card.Content>
      </Card.Root>
    </div>
  {/if}
{:else if isPhone()}
  <!-- 手机（浏览器或已安装的 App）：出示通行码 -->
  <div class="flex min-h-svh flex-col items-center justify-center gap-4 p-6 text-center">
    <h1 class="text-xl font-semibold">慧湖通 · 通行二维码</h1>

    <!-- The gain-map background stays inside the QR card's border: the rest
        of the page keeps its normal (SDR) background. The background is a
        dedicated <img> layer (not a CSS background) so the 10s QR re-render
        doesn't re-composite it — WebKit drops HDR appearance momentarily when
        overlapping layers with gain-map backgrounds are touched. No filter/
        opacity/transform may sit on the img — those clamp the gain map to SDR. -->
    <div class="bg-card relative overflow-hidden rounded-xl border p-5">
      {#if hdrDisplay && qrPath && !inactive}
        <img
          src={hdrWhiteUrl}
          alt=""
          aria-hidden="true"
          decoding="sync"
          style:dynamic-range-limit="no-limit"
          class="pointer-events-none absolute inset-0 h-full w-full"
        />
      {/if}
      <div class="relative w-[min(72vmin,560px)]">
        {#if qrPath && qrModules}
          <div class={inactive ? 'opacity-20 grayscale' : ''}>
            <svg
              viewBox="0 0 {qrModules} {qrModules}"
              preserveAspectRatio="xMinYMin meet"
              class="h-auto w-full"
            >
              <path d={qrPath} fill="black" />
            </svg>
          </div>
        {:else}
          <div class="text-muted-foreground grid h-[min(72vmin,560px)] place-items-center">
            {error ? '获取失败' : '正在获取…'}
          </div>
        {/if}
      </div>
    </div>

    {#if error}
      <Alert.Root variant="destructive" class="max-w-xl">
        <Alert.Title>刷新失败</Alert.Title>
        <Alert.Description>{error}</Alert.Description>
      </Alert.Root>
    {:else if info}
      <div class="text-status-ok font-medium">{info.text}</div>
    {/if}

    {#if info}
      <div class="text-muted-foreground text-sm leading-6">
        {info.name}
        <br />
        {info.apartment}
        {#if info.companyName}
          <br />
          {info.companyName}
        {/if}
      </div>
    {/if}

    <div class="text-muted-foreground/70 text-xs">
      {#if issuedAt}
        {issuedTime(issuedAt)}
        · {countdown}s
      {/if}
    </div>

    <div class="flex flex-wrap items-center justify-center gap-2">
      <Button onclick={toggleFullscreen}>
        {#if isFullscreen}
          <Minimize2Icon />
          退出全屏
        {:else}
          <Maximize2Icon />
          全屏
        {/if}
      </Button>
      {#if !standalone}
        <Button
          size={phoneBrowser ? 'sm' : 'icon-sm'}
          href={resolve('/guide')}
          aria-label="手机安装指南"
          title="手机安装指南"
        >
          <BookOpenIcon />
          {#if phoneBrowser}手机安装指南{/if}
        </Button>
      {/if}
      <Button
        variant="outline"
        size={phoneBrowser ? 'icon' : 'default'}
        aria-label="发送到其他设备"
        title="发送到其他设备"
        onclick={() => openPairing(openid!)}
      >
        <ShareIcon />
        {#if !phoneBrowser}发送到其他设备{/if}
      </Button>
      <Button variant="ghost" size="sm" class="text-muted-foreground" onclick={forget}>
        <RefreshCwIcon />
        更换 Open ID
      </Button>
    </div>

    {#if fullscreenHint}
      <p class="text-status-err max-w-xl text-xs">{fullscreenHint}</p>
    {/if}
  </div>
{:else}
  <div class="flex min-h-svh items-center justify-center p-6">
    <Card.Root class="w-full max-w-xl">
      <Card.Header>
        <Card.Title class="flex items-center gap-2">
          <CircleCheckIcon class="text-status-ok size-5" />
          Open ID 验证成功
        </Card.Title>
        <Card.Description>请查阅「手机安装指南」完成后续步骤。</Card.Description>
      </Card.Header>
      <Card.Content class="flex flex-col gap-4">
        {#if info}
          <Card.Root class="bg-muted/50 py-4 shadow-none">
            <Card.Content class="text-muted-foreground text-center text-sm leading-6">
              <p>{info.name}</p>
              {#if info.apartment}
                <p>{info.apartment}</p>
              {/if}
              {#if info.companyName}
                <p>{info.companyName}</p>
              {/if}
            </Card.Content>
          </Card.Root>
        {/if}
        <div class="grid gap-2 sm:grid-cols-2">
          <Button href={resolve('/guide')}>
            <BookOpenIcon />
            手机安装指南
          </Button>
          <Button variant="outline" onclick={() => openPairing(openid!)}>
            <ShareIcon />
            出示配对码
          </Button>
        </div>
        <Button variant="ghost" size="sm" class="text-muted-foreground" onclick={forget}>
          <RefreshCwIcon />
          更换 Open ID
        </Button>
      </Card.Content>
    </Card.Root>
  </div>
{/if}

{#if browser && booted}
  <QrScanner bind:open={scannerOpen} onresult={onScan} />
  <PairingDialog bind:open={pairingOpen} openId={pairingOpenId} />
{/if}
